import{_ as s,o as a,c as r,ax as t}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Passing User Context","description":"How to securely pass user identity and context to connectors using server-side template variables instead of browser-supplied parameters","frontmatter":{"description":"How to securely pass user identity and context to connectors using server-side template variables instead of browser-supplied parameters"},"headers":[],"relativePath":"connectors/passing-user-context.md","filePath":"connectors/passing-user-context.md"}'),i={name:"connectors/passing-user-context.md"};function n(o,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/passing-user-context.md for this page in Markdown format</div><h1 id="passing-user-context" tabindex="-1">Passing User Context <a class="header-anchor" href="#passing-user-context" aria-label="Permalink to &quot;Passing User Context&quot;">​</a></h1><p>Use this guide when your connector needs to identify the logged-in user — for example, to fetch their records from a CRM, personalize content, or enforce access control on an external API.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>An existing connector configured in <strong>Integrations</strong> → <strong>Developer Studio</strong> → <strong>Connectors</strong> (see <a href="./build-first-connector.html">Build Your First Connector</a> if you do not have one yet)</li><li>The external API accepts a user identifier (user ID, email, or similar) as a query parameter, header, or request body field</li></ul><h2 id="browser-data-vs-server-side-variables" tabindex="-1">Browser data vs server-side variables <a class="header-anchor" href="#browser-data-vs-server-side-variables" aria-label="Permalink to &quot;Browser data vs server-side variables&quot;">​</a></h2><p>Every connector request passes through a <a href="./how-connectors-work.html">server-side pipeline</a> before reaching the external API. During this pipeline, template variables like <code>{{ user.id }}</code> are resolved from the authenticated session — the browser cannot see or tamper with these values.</p><p>Everything the browser sends — query parameters, headers, request bodies — can be modified by the user. A malicious user can open browser dev tools and change <code>userId=123</code> to <code>userId=456</code> before the request leaves. Server-side template variables like <code>{{ user.id }}</code> are resolved on the backend from the authenticated session, so the user cannot tamper with them.</p><h2 id="use-server-side-variables-for-identity" tabindex="-1">Use server-side variables for identity <a class="header-anchor" href="#use-server-side-variables-for-identity" aria-label="Permalink to &quot;Use server-side variables for identity&quot;">​</a></h2><p>When a connector needs to know <em>who</em> the user is, set the value in the connector&#39;s configuration using a template variable. Do not pass it from browser JavaScript.</p><div class="danger custom-block"><p class="custom-block-title">Wrong: passing identity from the browser</p><p>The browser controls <code>queryParams</code>, so a user can change the value to impersonate someone else.</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Browser code — user can tamper with the ID</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sdk</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WidgetServiceSDK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sdk.connectors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  permalink: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user-profile-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  method: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  queryParams: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user_id: currentUser.id  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// attacker changes this in dev tools</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></div><div class="tip custom-block"><p class="custom-block-title">Right: set the variable in connector config</p><p>In the connector&#39;s <strong>Query Parameters</strong> section, add a non-overridable parameter:</p><ul><li><strong>Query Key</strong>: <code>user_id</code></li><li><strong>Query Value</strong>: <code>{{ user.id }}</code></li><li><strong>Overridable</strong>: unchecked</li></ul><p>The server resolves <code>{{ user.id }}</code> from the authenticated session. The browser never sees or controls this value.</p></div><p>Server-side variables are available in any connector field (URL, headers, query parameters, authentication, payload template, response template) — see <a href="./template-variables.html">Template Variables</a> for the full reference, including filters, functions, and availability per field.</p><h2 id="when-browser-parameters-are-appropriate" tabindex="-1">When browser parameters are appropriate <a class="header-anchor" href="#when-browser-parameters-are-appropriate" aria-label="Permalink to &quot;When browser parameters are appropriate&quot;">​</a></h2><p>Not all data needs server-side protection. The rule is: <strong>anything the user could legitimately change is fine as a <code>queryParam</code>; anything that identifies who the user is must come from server-side variables.</strong></p><p>Browser-supplied parameters are appropriate for:</p><ul><li>Search terms (<code>q=react hooks</code>)</li><li>Filters (<code>category=billing</code>)</li><li>Pagination (<code>page=3</code>, <code>limit=25</code>)</li><li>Sort order (<code>sort=created_at&amp;dir=desc</code>)</li></ul><p>These values carry no security risk if the user changes them — they only affect what the user sees, not <em>whose</em> data they see.</p><h2 id="the-overridable-checkbox" tabindex="-1">The Overridable checkbox <a class="header-anchor" href="#the-overridable-checkbox" aria-label="Permalink to &quot;The Overridable checkbox&quot;">​</a></h2><p>Each header and query parameter has an <strong>Overridable</strong> flag. For identity fields, always leave <strong>Overridable</strong> unchecked — this guarantees the server-side template variable cannot be replaced by browser code. Use <strong>Overridable</strong> only for values the user should legitimately control, like search terms or pagination. See <a href="./headers-and-query-parameters.html#overridable-fields">Headers &amp; Query Parameters</a> for the full explanation.</p><h2 id="common-patterns" tabindex="-1">Common patterns <a class="header-anchor" href="#common-patterns" aria-label="Permalink to &quot;Common patterns&quot;">​</a></h2><h3 id="pass-the-logged-in-user-s-id-to-an-external-api" tabindex="-1">Pass the logged-in user&#39;s ID to an external API <a class="header-anchor" href="#pass-the-logged-in-user-s-id-to-an-external-api" aria-label="Permalink to &quot;Pass the logged-in user&#39;s ID to an external API&quot;">​</a></h3><p>In the connector&#39;s <strong>Query Parameters</strong>:</p><ul><li><strong>Query Key</strong>: <code>user_id</code> — <strong>Query Value</strong>: <code>{{ user.id }}</code> — <strong>Overridable</strong>: unchecked</li></ul><h3 id="pass-user-email-for-personalized-lookups" tabindex="-1">Pass user email for personalized lookups <a class="header-anchor" href="#pass-user-email-for-personalized-lookups" aria-label="Permalink to &quot;Pass user email for personalized lookups&quot;">​</a></h3><p>In the connector&#39;s <strong>Query Parameters</strong>:</p><ul><li><strong>Query Key</strong>: <code>email</code> — <strong>Query Value</strong>: <code>{{ user.email }}</code> — <strong>Overridable</strong>: unchecked</li></ul><h3 id="pass-tenant-id-for-multi-tenant-apis" tabindex="-1">Pass tenant ID for multi-tenant APIs <a class="header-anchor" href="#pass-tenant-id-for-multi-tenant-apis" aria-label="Permalink to &quot;Pass tenant ID for multi-tenant APIs&quot;">​</a></h3><p>In the connector&#39;s <strong>Headers</strong>:</p><ul><li><strong>Header Key</strong>: <code>X-Tenant-ID</code> — <strong>Header Value</strong>: <code>{{ tenant_id }}</code> — <strong>Overridable</strong>: unchecked</li></ul><h3 id="pass-a-custom-profile-field" tabindex="-1">Pass a custom profile field <a class="header-anchor" href="#pass-a-custom-profile-field" aria-label="Permalink to &quot;Pass a custom profile field&quot;">​</a></h3><p>In the connector&#39;s <strong>Query Parameters</strong>:</p><ul><li><strong>Query Key</strong>: <code>department</code> — <strong>Query Value</strong>: <code>{{ user.profile_fields.by_id(42) }}</code> — <strong>Overridable</strong>: unchecked</li></ul><p>Replace <code>42</code> with the numeric ID of the profile field from your community&#39;s Profile Fields settings.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./template-variables.html">Template Variables</a> — Full reference of variables, filters, and functions</li><li><a href="./headers-and-query-parameters.html">Headers &amp; Query Parameters</a> — Configure static and overridable values</li><li><a href="./calling-from-widgets.html">Calling from Widget Code</a> — Invoke connectors from widget JavaScript</li><li><a href="./filtering-sensitive-data.html">Filtering Sensitive Data</a> — Keep hidden or private records out of responses</li><li><a href="./authentication.html">Authentication</a> — Secure your connector&#39;s external API requests</li></ul>`,36)])])}const g=s(i,[["render",n]]);export{u as __pageData,g as default};
